import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';

if (!process.env.AI_TRADING_DATA_DIR) {
  const tempDir = fs.mkdtempSync(path.join(os.tmpdir(), 'ai-trading-test-'));
  process.env.AI_TRADING_DATA_DIR = tempDir;
  process.env.AI_TRADING_DB_PATH = path.join(tempDir, 'trading.db');

  process.once('exit', () => {
    try {
      fs.rmSync(tempDir, { recursive: true, force: true });
    } catch {}
  });
}

process.env.NODE_ENV = 'test';

import { test, describe } from 'node:test';
import assert from 'node:assert';
import crypto from 'crypto';
import { scoreHeadline, aggregateCoinSentiment } from '../src/services/signals/lexicon.js';
import { detectThreats, isSymbolThreatened } from '../src/services/signals/threat.js';
import { detectBtcRegime } from '../src/services/signals/regime.js';
import { scoreOpportunity, SCORE_THRESHOLDS } from '../src/services/signals/scorer.js';
import {
  checkCircuitBreaker,
  checkExposure,
  checkBtcRegime,
  checkThreatScope,
  checkSlippageBudget,
  checkSpreadTrap,
  checkRsiGuard,
  RiskState,
} from '../src/services/trading/riskGuard.js';
import { agentBus } from '../src/services/agents/bus.js';
import { IndodaxAdapter } from '../src/services/adapters/IndodaxAdapter.js';
import { CoinFeatures, ThreatSignal } from '../src/services/signals/types.js';

describe('Section 9 Lexicon Sentiment Scoring & Age Decay', () => {
  test('accurately scores bilingual Indonesian and English sentiment keywords', () => {
    const bullishId = 'Bank Indonesia perkuat adopsi dan kemitraan aset kripto nasional lonjakan volume';
    const scoreBullish = scoreHeadline(bullishId);
    assert.ok(scoreBullish.score > 0.3, `Expected score > 0.3, got ${scoreBullish.score}`);
    assert.ok(scoreBullish.matchedBullish.includes('kemitraan'));
    assert.ok(scoreBullish.matchedBullish.includes('adopsi'));

    const bearishEn = 'Major exchange crash liquidation dump panic anjlok drastis';
    const scoreBearish = scoreHeadline(bearishEn);
    assert.ok(scoreBearish.score < -0.3, `Expected score < -0.3, got ${scoreBearish.score}`);
    assert.ok(scoreBearish.matchedBearish.includes('liquidation'));
    assert.ok(scoreBearish.matchedBearish.includes('anjlok'));

    // Neutral text returns 0
    const neutral = 'Indodax merilis jadwal pemeliharaan rutin server pada hari minggu malam.';
    const scoreNeutral = scoreHeadline(neutral);
    assert.strictEqual(scoreNeutral.score, 0);
  });

  test('tanh scaling bounds sentiment scores strictly within [-1.0, 1.0]', () => {
    const extremeBullish = 'etf breakout pump partnership surge moon rekor kemitraan '.repeat(10);
    const result = scoreHeadline(extremeBullish);
    assert.ok(result.score <= 1.0 && result.score >= -1.0);
  });

  test('scoreHeadline is purely deterministic (identical input produces identical score and matches)', () => {
    const text = 'Bitcoin melonjak menembus level rekor setelah kemitraan institusional disetujui';
    const res1 = scoreHeadline(text);
    const res2 = scoreHeadline(text);

    assert.strictEqual(res1.score, res2.score);
    assert.deepStrictEqual(res1.matchedBullish, res2.matchedBullish);
    assert.deepStrictEqual(res1.matchedBearish, res2.matchedBearish);
    assert.deepStrictEqual(res1.mentionedCoins, res2.mentionedCoins);
    assert.ok(res1.score >= -1.0 && res1.score <= 1.0);
  });

  test('aggregateCoinSentiment applies 48-hour age decay weighting', () => {
    const itemFresh = {
      sentiment: { score: 0.8, matchedBullish: ['partnership'], matchedBearish: [], mentionedCoins: ['btc'] },
      ageHours: 2,
    };
    const itemDecayed = {
      sentiment: { score: -0.4, matchedBullish: [], matchedBearish: ['drop'], mentionedCoins: ['btc'] },
      ageHours: 40,
    };
    const itemAncient = {
      sentiment: { score: 1.0, matchedBullish: ['moon'], matchedBearish: [], mentionedCoins: ['btc'] },
      ageHours: 50, // > 48h, weight 0
    };

    const res = aggregateCoinSentiment([itemFresh, itemDecayed, itemAncient]);
    // Fresh bullish (weight 46/48) dominates decayed bearish (weight 8/48), ancient ignored
    assert.ok(res.btc > 0, `Expected positive aggregated sentiment, got ${res.btc}`);

    const resAncientOnly = aggregateCoinSentiment([itemAncient]);
    assert.strictEqual(resAncientOnly.btc ?? 0, 0);
  });
});

describe('P0-A Fix: Scoped Threat Blocker & False Alarm Elimination', () => {
  test('bare word "sec" or "second" does NOT trigger false emergency threats', () => {
    const benignHeadlines = [
      'SEC approves options trading for spot Bitcoin ETFs',
      'Ethereum layer 2 completes transactions in under one second',
      'Crypto exchange security audit passes with high marks',
    ];

    for (const title of benignHeadlines) {
      const threats = detectThreats({ title, fetchedAt: Date.now() });
      assert.strictEqual(threats.length, 0, `False threat triggered for: "${title}"`);
    }
  });

  test('genuine critical threats (lawsuit charges, exploits, hacks) are correctly detected', () => {
    const exploitNews = {
      title: 'Solana DeFi protocol smart contract exploited in hack attack',
      fetchedAt: Date.now(),
    };
    const threats = detectThreats(exploitNews);

    assert.ok(threats.length >= 1);
    assert.strictEqual(threats[0].coin?.toLowerCase(), 'sol');
    assert.ok(threats[0].severity === 'critical' || threats[0].severity === 'high');
  });

  test('threat scoping: an exploit on PEPE does not block BTC or ETH', () => {
    const now = Date.now();
    const pepeThreat: ThreatSignal = {
      coin: 'pepe',
      severity: 'critical',
      matchedRule: 'exploit',
      headline: 'PEPE smart contract exploit confirmed',
      detectedAt: now,
    };

    const threats = [pepeThreat];

    // Check PEPE
    const pepeBlock = checkThreatScope('pepe_idr', threats, now);
    assert.strictEqual(pepeBlock.passed, false);

    // Check BTC - MUST PASS!
    const btcBlock = checkThreatScope('btc_idr', threats, now);
    assert.strictEqual(btcBlock.passed, true);

    // Check ETH - MUST PASS!
    const ethBlock = checkThreatScope('eth_idr', threats, now);
    assert.strictEqual(ethBlock.passed, true);
  });

  test('threat expiration: threats older than 30 minutes automatically expire', () => {
    const now = Date.now();
    const expiredThreat: ThreatSignal = {
      coin: 'btc',
      severity: 'high',
      matchedRule: 'outage',
      headline: 'Exchange temporary outage reported 35 minutes ago',
      detectedAt: now - 35 * 60 * 1000, // 35m old
    };

    assert.strictEqual(isSymbolThreatened('btc', [expiredThreat], now), false);
    const scopeCheck = checkThreatScope('btc_idr', [expiredThreat], now);
    assert.strictEqual(scopeCheck.passed, true);
  });
});

describe('BTC Macro Regime Window Returns (1h & 4h)', () => {
  test('detects CRASH regime when 1h return <= -3% or 4h return <= -5%', () => {
    // 1h flash drop of -3.5%
    const verdict1h = detectBtcRegime({
      close: 96500,
      change1hPct: -3.5,
      change4hPct: -0.5,
      ema21_1h: 99000,
      atrPercentile30d: 50,
    });
    assert.strictEqual(verdict1h.regime, 'CRASH');
    assert.strictEqual(verdict1h.allowNewEntries, false);

    // 4h cumulative dump of -5.2%
    const verdict4h = detectBtcRegime({
      close: 94800,
      change1hPct: -1.25,
      change4hPct: -5.2,
      ema21_1h: 98000,
      atrPercentile30d: 60,
    });
    assert.strictEqual(verdict4h.regime, 'CRASH');
    assert.strictEqual(verdict4h.allowNewEntries, false);
  });

  test('normal intraday fluctuation below 24h high does NOT trigger CRASH', () => {
    // Normal 1h return of -0.4% and 4h -0.8%
    const normalVerdict = detectBtcRegime({
      close: 98000,
      change1hPct: -0.4,
      change4hPct: -0.8,
      ema21_1h: 97500, // close > EMA21
      atrPercentile30d: 50,
    });
    assert.notStrictEqual(normalVerdict.regime, 'CRASH');
    assert.strictEqual(normalVerdict.allowNewEntries, true);
  });

  test('identifies RISK_ON when price is above EMA21 with healthy momentum', () => {
    const riskOnVerdict = detectBtcRegime({
      close: 102000,
      change1hPct: 1.5,
      change4hPct: 2.0,
      ema21_1h: 100500,
      atrPercentile30d: 45,
    });
    assert.strictEqual(riskOnVerdict.regime, 'RISK_ON');
    assert.strictEqual(riskOnVerdict.allowNewEntries, true);
  });
});

describe('Conservative Blue-Chip Pullback Opportunity Scoring', () => {
  const baseBtcFeatures: CoinFeatures = {
    symbol: 'btc',
    close: 1550000000,
    high24h: 1580000000,
    low24h: 1520000000,
    volume24hIdr: 45000000000,
    rsi14: 42,            // Dip near structural support
    ema21: 1540000000,    // Price above EMA21 (1550 > 1540)
    ema50: 1500000000,
    atr14: 25000000,
    gain24hPct: 1.5,
    dropFromHighPct: -1.9, // Healthy -1.9% dip from 24h high
    volumeSurgeRatio: 1.2,
    spreadPct: 0.04,
    depthImbalance: 1.8,  // Strong buyer wall
    isBluechip: true,
  };

  test('scores high on conservative bluechip pullback during healthy dip', () => {
    const result = scoreOpportunity(
      baseBtcFeatures,
      0.45,   // positive lexicon sentiment
      false,  // no threat
      'RISK_ON',
      'bluechip_pullback'
    );
    assert.strictEqual(result.strategy, 'bluechip_pullback');
    assert.ok(
      result.score >= SCORE_THRESHOLDS.conservative,
      `Score ${result.score} should pass threshold ${SCORE_THRESHOLDS.conservative}`
    );
    assert.ok(result.breakdown.rsi > 0);
    assert.ok(result.breakdown.dip > 0);
    assert.ok(result.breakdown.trend > 0);
  });

  test('threat immediately vetos score to zero', () => {
    const result = scoreOpportunity(
      baseBtcFeatures,
      0.45,
      true, // Threat active!
      'RISK_ON',
      'bluechip_pullback'
    );
    assert.strictEqual(result.score, 0);
    assert.strictEqual(result.breakdown.threat_veto, 0);
  });

  test('bluechip pullback fails closed when RSI or EMA21 is missing', () => {
    const missingRsi = scoreOpportunity(
      { ...baseBtcFeatures, rsi14: null },
      0.45,
      false,
      'RISK_ON',
      'bluechip_pullback'
    );
    assert.strictEqual(missingRsi.score, 0);
    assert.strictEqual(missingRsi.breakdown.missing_indicators, 0);

    const missingEma = scoreOpportunity(
      { ...baseBtcFeatures, ema21: null },
      0.45,
      false,
      'RISK_ON',
      'bluechip_pullback'
    );
    assert.strictEqual(missingEma.score, 0);
    assert.strictEqual(missingEma.breakdown.missing_indicators, 0);
  });

  test('momentum score fails closed when RSI is missing', () => {
    const result = scoreOpportunity(
      { ...baseBtcFeatures, rsi14: null },
      0.45,
      false,
      'RISK_ON',
      'momentum'
    );
    assert.strictEqual(result.score, 0);
    assert.strictEqual(result.breakdown.missing_indicators, 0);
  });
});

describe('Pure Risk Guard Execution Pipeline (Gates 1-8)', () => {
  const healthyState: RiskState = {
    dailyPnlIdr: 100000,
    dayStartEquityIdr: 10000000,
    openPositions: 1,
    regimeAllowEntries: true,
    btcChange1hPct: 0.5,
    btcChange4hPct: 1.2,
  };

  test('checkCircuitBreaker halts entries if daily loss exceeds limit', () => {
    assert.strictEqual(checkCircuitBreaker(healthyState, 5.0).passed, true);

    const losingState: RiskState = {
      ...healthyState,
      dailyPnlIdr: -600000, // 6% loss
    };
    assert.strictEqual(checkCircuitBreaker(losingState, 5.0).passed, false);
  });

  test('checkExposure halts entries when position capacity is reached', () => {
    assert.strictEqual(checkExposure(healthyState, 3).passed, true);

    const fullState: RiskState = {
      ...healthyState,
      openPositions: 3,
    };
    assert.strictEqual(checkExposure(fullState, 3).passed, false);
  });

  test('checkBtcRegime gates entries based on BTC 1h flash crash threshold', () => {
    assert.strictEqual(checkBtcRegime(healthyState, -3.0).passed, true);

    const crashState: RiskState = {
      ...healthyState,
      regimeAllowEntries: false,
      btcChange1hPct: -3.5,
    };
    assert.strictEqual(checkBtcRegime(crashState, -3.0).passed, false);
  });

  test('checkSpreadTrap prevents entry when bid-ask spread is excessively wide', () => {
    assert.strictEqual(checkSpreadTrap(0.4, 0.8).passed, true);
    assert.strictEqual(checkSpreadTrap(1.2, 0.8).passed, false);
  });

  test('checkRsiGuard prevents buying top of parabolic candles', () => {
    assert.strictEqual(checkRsiGuard(62, 70).passed, true);
    assert.strictEqual(checkRsiGuard(74, 70).passed, false);
    assert.strictEqual(checkRsiGuard(null, 70).passed, true); // missing data passes gracefully
  });

  test('checkSlippageBudget verifies estimated fill against tolerance', () => {
    assert.strictEqual(checkSlippageBudget(0.3, 0.8).passed, true);
    assert.strictEqual(checkSlippageBudget(1.1, 0.8).passed, false);
  });
});

describe('P0-B Fix: Context Fingerprinting & Swarm Deduplication', () => {
  test('contextFingerprint produces deterministic SHA256 hashes', () => {
    const payload = JSON.stringify({
      headlines: ['Bank Indonesia dukung adopsi aset digital'],
      prices: { btc: 1550000000, eth: 45000000 },
    });

    const hash1 = crypto.createHash('sha256').update(payload).digest('hex').substring(0, 16);
    const hash2 = crypto.createHash('sha256').update(payload).digest('hex').substring(0, 16);

    assert.strictEqual(hash1, hash2);
    assert.strictEqual(hash1.length, 16);

    // Any alteration produces different hash
    const alteredPayload = JSON.stringify({
      headlines: ['Bank Indonesia dukung adopsi aset digital'],
      prices: { btc: 1550000001, eth: 45000000 },
    });
    const hashAltered = crypto.createHash('sha256').update(alteredPayload).digest('hex').substring(0, 16);
    assert.notStrictEqual(hash1, hashAltered);
  });
});

describe('Multi-Agent Blackboard Bus & Outbox Persistence', () => {
  test('agentBus delivers events to subscribers and writes to SQLite outbox', () => {
    let receivedPayload: any = null;

    const unsubscribe = agentBus.subscribe('opportunity.signal', (msg) => {
      receivedPayload = msg.payload;
    });

    const msg = agentBus.publish(
      'opportunity.signal',
      'test_runner',
      { score: 85, profile: 'conservative', symbol: 'btc_idr' }
    );

    assert.ok(receivedPayload !== null);
    assert.strictEqual(receivedPayload.score, 85);
    assert.strictEqual(receivedPayload.profile, 'conservative');

    unsubscribe();

    // Verify durable SQLite outbox
    const recent = agentBus.getRecentMessages('opportunity.signal', 5);
    const found = recent.find((m) => m.id === msg.id);
    assert.ok(found !== undefined, 'Message should be persisted in agent_messages table');
    assert.strictEqual(found.payload.symbol, 'btc_idr');
  });
});

describe('Asset-Agnostic MarketAdapter Abstraction', () => {
  test('IndodaxAdapter conforms to MarketAdapter interface', async () => {
    const adapter = new IndodaxAdapter();
    assert.strictEqual(adapter.id, 'indodax');
    assert.strictEqual(adapter.name, 'Indodax');
    assert.strictEqual(adapter.assetClass, 'crypto');

    // Minimum trade size
    const minTrade = adapter.getMinTradeIdr('btc');
    assert.ok(minTrade >= 10000, `Min trade IDR should be at least 10000, got ${minTrade}`);

    // Paper order execution
    const paperOrder = await adapter.createOrder({
      symbol: 'btc',
      side: 'buy',
      type: 'market',
      price: 1550000000,
      amount: 0.001,
      mode: 'paper',
    });

    assert.strictEqual(paperOrder.success, true);
    assert.strictEqual(paperOrder.executedPrice, 1550000000);
    assert.strictEqual(paperOrder.executedAmount, 0.001);
  });
});

import type { HeadlineSentiment } from './types.js';

/** Kamus bullish: kata -> bobot +0.1 .. +1.0 */
const BULLISH_LEXICON: Record<string, number> = {
  // English
  surge: 0.8,
  soar: 0.9,
  soaring: 0.9,
  rally: 0.8,
  breakout: 0.7,
  bull: 0.6,
  bullish: 0.7,
  pump: 0.5,
  gains: 0.4,
  rise: 0.4,
  rising: 0.4,
  rebound: 0.5,
  recovery: 0.4,
  'all-time high': 0.9,
  ath: 0.9,
  adoption: 0.5,
  partnership: 0.4,
  upgrade: 0.4,
  approval: 0.6,
  approved: 0.6,
  institutional: 0.4,
  inflows: 0.3,
  accumulation: 0.4,
  'buy the dip': 0.4,
  milestone: 0.3,
  integration: 0.3,

  // Bahasa Indonesia
  melonjak: 0.8,
  melambung: 0.9,
  menguat: 0.5,
  naik: 0.4,
  pemulihan: 0.4,
  adopsi: 0.5,
  kemitraan: 0.4,
  persetujuan: 0.6,
  disetujui: 0.6,
  akumulasi: 0.4,
  tonggak: 0.3,
  integrasi: 0.3,
};

/** Kamus bearish: kata -> bobot -0.1 .. -1.0 */
const BEARISH_LEXICON: Record<string, number> = {
  // English
  crash: -0.9,
  crashes: -0.9,
  plunge: -0.8,
  plunges: -0.8,
  dump: -0.6,
  selloff: -0.7,
  'sell-off': -0.7,
  bear: -0.6,
  bearish: -0.7,
  decline: -0.4,
  declining: -0.4,
  drop: -0.4,
  drops: -0.4,
  fall: -0.4,
  falls: -0.4,
  correction: -0.4,
  liquidation: -0.6,
  liquidations: -0.6,
  fear: -0.5,
  panic: -0.7,
  fud: -0.5,
  outflow: -0.3,
  outflows: -0.3,
  resistance: -0.2,

  // Bahasa Indonesia
  turun: -0.4,
  jatuh: -0.5,
  melemah: -0.5,
  anjlok: -0.8,
  jual: -0.3,
  kepanikan: -0.7,
  koreksi: -0.4,
  likuidasi: -0.6,
};

function escapeRegExp(s: string): string {
  return s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

const COMPILED_BULLISH: Array<[RegExp, number]> = Object.entries(BULLISH_LEXICON).map(
  ([word, weight]) => [new RegExp(`\\b${escapeRegExp(word)}\\b`, 'i'), weight]
);

const COMPILED_BEARISH: Array<[RegExp, number]> = Object.entries(BEARISH_LEXICON).map(
  ([word, weight]) => [new RegExp(`\\b${escapeRegExp(word)}\\b`, 'i'), weight]
);

export const COIN_PATTERNS: Record<string, RegExp> = {
  BTC: /\b(bitcoin|btc)\b/i,
  ETH: /\b(ethereum|eth|ether)\b/i,
  SOL: /\b(solana|sol)\b/i,
  BNB: /\b(bnb|binance coin)\b/i,
  XRP: /\b(ripple|xrp)\b/i,
  DOGE: /\b(dogecoin|doge)\b/i,
  PEPE: /\b(pepe)\b/i,
  SHIB: /\b(shiba|shib)\b/i,
  USDT: /\b(tether|usdt)\b/i,
};

function round3(n: number): number {
  return Math.round(n * 1000) / 1000;
}

export function scoreHeadline(title: string, description = ''): HeadlineSentiment {
  const text = `${title} ${description}`;
  const matchedBullish: string[] = [];
  const matchedBearish: string[] = [];
  let raw = 0;

  for (const [re, weight] of COMPILED_BULLISH) {
    if (re.test(text)) {
      matchedBullish.push(re.source.replace(/\\b|\\/g, ''));
      raw += weight;
    }
  }

  for (const [re, weight] of COMPILED_BEARISH) {
    if (re.test(text)) {
      matchedBearish.push(re.source.replace(/\\b|\\/g, ''));
      raw += weight; // already negative
    }
  }

  const mentionedCoins = Object.entries(COIN_PATTERNS)
    .filter(([, re]) => re.test(text))
    .map(([symbol]) => symbol);

  // tanh maps raw sum smoothly to -1.0 .. +1.0
  const score = Math.tanh(raw / 2);

  return {
    score: round3(score),
    matchedBullish,
    matchedBearish,
    mentionedCoins,
  };
}

/** Agregasi sentimen per koin dari banyak headline (dengan decay usia berita max 48 jam) */
export function aggregateCoinSentiment(
  items: Array<{ sentiment: HeadlineSentiment; ageHours: number }>
): Record<string, number> {
  const acc: Record<string, { total: number; weight: number }> = {};

  for (const { sentiment, ageHours } of items) {
    const decay = Math.max(0, 1 - ageHours / 48);
    if (decay === 0) continue;

    for (const coin of sentiment.mentionedCoins) {
      if (!acc[coin]) acc[coin] = { total: 0, weight: 0 };
      acc[coin].total += sentiment.score * decay;
      acc[coin].weight += decay;
    }
  }

  const out: Record<string, number> = {};
  for (const [coin, { total, weight }] of Object.entries(acc)) {
    out[coin] = round3(weight > 0 ? total / weight : 0);
  }

  return out;
}

import type { NewsItem, ThreatSignal, ThreatSeverity } from './types.js';
import { COIN_PATTERNS } from './lexicon.js';

interface ThreatRule {
  pattern: RegExp;
  severity: ThreatSeverity;
  scope: 'coin' | 'global';
}

const THREAT_RULES: ThreatRule[] = [
  // Critical: direct asset or protocol exploit/hack/drain
  {
    pattern: /\b(hack|hacked|exploit|exploited|drained?|stolen|breach|vulnerability)\b/i,
    severity: 'critical',
    scope: 'coin',
  },
  {
    pattern: /\b(rug\s?pull|rugpull|exit scam|ponzi|fraud|scam)\b/i,
    severity: 'critical',
    scope: 'coin',
  },

  // High: listing status & exchange freeze
  {
    pattern: /\b(delist|delisting|delisted|suspend|suspended|freeze|frozen)\b/i,
    severity: 'high',
    scope: 'coin',
  },
  {
    pattern: /\b(indodax (down|maintenance|gangguan|error))\b/i,
    severity: 'high',
    scope: 'global',
  },

  // Medium: enforcement & regulatory charges (Bare 'sec' is intentionally NOT a threat!)
  {
    pattern: /\b(sec charges?|indicted?|arrested?|lawsuit filed|bappebti (block|ban|suspend))\b/i,
    severity: 'medium',
    scope: 'coin',
  },
];

export function detectThreats(item: NewsItem): ThreatSignal[] {
  const signals: ThreatSignal[] = [];
  const text = `${item.title} ${item.description || ''}`;

  for (const rule of THREAT_RULES) {
    if (!rule.pattern.test(text)) continue;

    if (rule.scope === 'coin') {
      const coins = Object.entries(COIN_PATTERNS)
        .filter(([, re]) => re.test(text))
        .map(([s]) => s);

      // If no specific coin is mentioned in the threat headline, do NOT falsely block all coins!
      if (coins.length === 0) continue;

      for (const coin of coins) {
        signals.push({
          coin,
          severity: rule.severity,
          matchedRule: String(rule.pattern),
          headline: item.title,
          detectedAt: item.fetchedAt || Date.now(),
        });
      }
    } else {
      signals.push({
        coin: null, // global systemic threat
        severity: rule.severity,
        matchedRule: String(rule.pattern),
        headline: item.title,
        detectedAt: item.fetchedAt || Date.now(),
      });
    }
  }

  return signals;
}

/** Check if a symbol is blocked by an active threat (freshness: < 30 minutes) */
export function isSymbolThreatened(
  symbol: string,
  activeThreats: ThreatSignal[],
  now = Date.now(),
  freshnessMs = 30 * 60 * 1000
): boolean {
  const cleanSymbol = symbol.toUpperCase().replace('_IDR', '');
  return activeThreats.some((t) => {
    const isTargetCoin = t.coin === null || t.coin.toUpperCase() === cleanSymbol;
    const isFresh = now - t.detectedAt < freshnessMs;
    return isTargetCoin && isFresh;
  });
}

import type { BtcRegimeInput, RegimeVerdict } from './types.js';

export function detectBtcRegime(input: BtcRegimeInput): RegimeVerdict {
  const reasons: string[] = [];

  // CRASH: Sharp downward movement in short window (1h <= -3% or 4h <= -5%)
  if (input.change1hPct <= -3.0 || input.change4hPct <= -5.0) {
    reasons.push(
      `BTC ${input.change1hPct.toFixed(2)}% (1j) / ${input.change4hPct.toFixed(2)}% (4j) — flash dump terdeteksi`
    );
    return { regime: 'CRASH', allowNewEntries: false, reasons };
  }

  const belowEma = input.ema21_1h != null ? input.close < input.ema21_1h : false;
  const highVolatility = input.atrPercentile30d != null && input.atrPercentile30d >= 80;

  if (belowEma && highVolatility) {
    reasons.push('BTC di bawah EMA21 (1j) dengan volatilitas tinggi (ATR pct >= 80)');
    return { regime: 'RISK_OFF', allowNewEntries: true, reasons };
  }

  if (input.change1hPct >= 1.0 && !belowEma) {
    reasons.push(`BTC +${input.change1hPct.toFixed(2)}% (1j) dan di atas EMA21`);
    return { regime: 'RISK_ON', allowNewEntries: true, reasons };
  }

  reasons.push(`BTC stabil: 1h: ${input.change1hPct.toFixed(2)}%, 4h: ${input.change4hPct.toFixed(2)}%`);
  return { regime: 'NEUTRAL', allowNewEntries: true, reasons };
}

import type { CoinFeatures, MarketRegime, ScoreResult, Strategy } from './types.js';

const clamp = (v: number, lo: number, hi: number) => Math.min(hi, Math.max(lo, v));

/** Skor 0..100: semakin dekat ke rentang ideal semakin tinggi */
function bandScore(value: number, idealLo: number, idealHi: number, hardLo: number, hardHi: number): number {
  if (value < hardLo || value > hardHi) return 0;
  if (value >= idealLo && value <= idealHi) return 100;
  const dist = value < idealLo ? idealLo - value : value - idealHi;
  const maxDist = value < idealLo ? idealLo - hardLo : hardHi - idealHi;
  if (maxDist <= 0) return 100;
  return clamp(100 - (dist / maxDist) * 100, 0, 100);
}

export function scoreOpportunity(
  f: CoinFeatures,
  coinSentiment: number, // -1.0 .. +1.0 from lexicon
  threatActive: boolean,
  regime: MarketRegime,
  strategy: Strategy
): ScoreResult {
  const breakdown: Record<string, number> = {};
  let score = 0;

  if (threatActive) {
    return { symbol: f.symbol, strategy, score: 0, breakdown: { threat_veto: 0 } };
  }

  if (strategy === 'bluechip_pullback') {
    // Missing indicators must not be imputed into a tradable score.
    if (f.rsi14 === null || f.ema21 === null) {
      return { symbol: f.symbol, strategy, score: 0, breakdown: { missing_indicators: 0 } };
    }
    // Konservatif: beli pullback pada blue-chip sehat
    const rsi = f.rsi14;
    const rsiScore = rsi < 35 ? 100 : rsi < 48 ? 85 : rsi <= 60 ? 50 : 0;
    // Dip score: drop from high is between -0.5% and -8% (healthy dip, not crashing)
    const dipScore = bandScore(f.dropFromHighPct, -4, -0.5, -9, 0.5);
    const trendScore = f.close >= f.ema21 ? 100 : 40;
    const sentimentScore = clamp((coinSentiment + 1) * 50, 0, 100);
    const qualityScore = clamp(100 - f.spreadPct * 50, 0, 100);

    breakdown.rsi = Math.round(rsiScore * 0.25);
    breakdown.dip = Math.round(dipScore * 0.30);
    breakdown.trend = Math.round(trendScore * 0.25);
    breakdown.sentiment = Math.round(sentimentScore * 0.10);
    breakdown.quality = Math.round(qualityScore * 0.10);
    score = Object.values(breakdown).reduce((a, b) => a + b, 0);
  } else if (strategy === 'momentum') {
    if (f.rsi14 === null) {
      return { symbol: f.symbol, strategy, score: 0, breakdown: { missing_indicators: 0 } };
    }
    // Balanced: momentum band (2-12%) dengan konfirmasi volume & depth imbalance
    const gainScore = bandScore(f.gain24hPct, 2, 10, 0, 20);
    const volumeScore = clamp((f.volumeSurgeRatio - 0.8) * 60, 0, 100);
    const depthScore = clamp((f.depthImbalance - 0.8) * 100, 0, 100);
    const rsiScore = f.rsi14 > 70 ? 0 : f.rsi14 < 30 ? 70 : 100;
    const sentimentScore = clamp((coinSentiment + 1) * 50, 0, 100);

    breakdown.gain = Math.round(gainScore * 0.30);
    breakdown.volume = Math.round(volumeScore * 0.25);
    breakdown.depth = Math.round(depthScore * 0.20);
    breakdown.rsi = Math.round(rsiScore * 0.15);
    breakdown.sentiment = Math.round(sentimentScore * 0.10);
    score = Object.values(breakdown).reduce((a, b) => a + b, 0);
  } else {
    // new_listing: butuh volume & momentum awal
    const volumeScore = clamp((f.volumeSurgeRatio - 1.5) * 50, 0, 100);
    const gainScore = bandScore(f.gain24hPct, 5, 30, 0, 100);
    breakdown.volume = Math.round(volumeScore * 0.60);
    breakdown.gain = Math.round(gainScore * 0.40);
    score = Object.values(breakdown).reduce((a, b) => a + b, 0);
  }

  // Regime adjustment: RISK_OFF requires higher score hurdle
  if (regime === 'RISK_OFF') {
    score -= 10;
    breakdown.regime_penalty = -10;
  }

  return {
    symbol: f.symbol,
    strategy,
    score: clamp(Math.round(score), 0, 100),
    breakdown,
  };
}

export const SCORE_THRESHOLDS: Record<'conservative' | 'balanced' | 'aggressive', number> = {
  conservative: 65,
  balanced: 60,
  aggressive: 50,
};

import { isSymbolThreatened } from '../signals/threat.js';
import type { ThreatSignal } from '../signals/types.js';

export interface RiskState {
  dailyPnlIdr: number;
  dayStartEquityIdr: number;
  openPositions: number;
  paperBalanceIdr?: number;
  regimeAllowEntries: boolean;
  btcChange1hPct: number;
  btcChange4hPct?: number;
}

export interface GateResult {
  passed: boolean;
  reason: string;
  values: Record<string, number | string | boolean>;
}

function round2(n: number): number {
  return Math.round(n * 100) / 100;
}

export function checkCircuitBreaker(s: RiskState, dailyLossLimitPct: number): GateResult {
  const lossPct = s.dayStartEquityIdr > 0 ? (-s.dailyPnlIdr / s.dayStartEquityIdr) * 100 : 0;
  const passed = s.dailyPnlIdr >= 0 || lossPct < dailyLossLimitPct;
  return {
    passed,
    reason: passed
      ? 'Daily loss dalam batas aman'
      : `Daily loss ${lossPct.toFixed(2)}% >= limit ${dailyLossLimitPct}%`,
    values: { lossPct: round2(lossPct), limitPct: dailyLossLimitPct },
  };
}

export function checkExposure(s: RiskState, maxActiveTrades: number): GateResult {
  const passed = s.openPositions < maxActiveTrades;
  return {
    passed,
    reason: passed ? 'Slot posisi tersedia' : `Slot penuh (${s.openPositions}/${maxActiveTrades})`,
    values: { open: s.openPositions, max: maxActiveTrades },
  };
}

export function checkBtcRegime(s: RiskState, crashThreshold1hPct = -3.0): GateResult {
  const passed = s.regimeAllowEntries && s.btcChange1hPct > crashThreshold1hPct;
  return {
    passed,
    reason: passed
      ? 'BTC regime stabil'
      : `BTC ${s.btcChange1hPct.toFixed(2)}% (1j) — flash dump terdeteksi`,
    values: { btcChange1hPct: round2(s.btcChange1hPct), threshold: crashThreshold1hPct },
  };
}

export function checkThreatScope(
  symbol: string,
  activeThreats: ThreatSignal[],
  now = Date.now()
): GateResult {
  const threatened = isSymbolThreatened(symbol, activeThreats, now);
  return {
    passed: !threatened,
    reason: threatened
      ? `Threat aktif untuk ${symbol.toUpperCase()} (<30 menit)`
      : 'Tidak ada threat aktif untuk koin ini',
    values: { symbol, threatCount: activeThreats.length },
  };
}

export function checkSlippageBudget(slippagePct: number, tolerancePct: number): GateResult {
  const passed = slippagePct <= tolerancePct;
  return {
    passed,
    reason: passed
      ? 'Slippage dalam toleransi'
      : `Slippage ${slippagePct.toFixed(2)}% > toleransi ${tolerancePct}%`,
    values: { slippagePct: round2(slippagePct), tolerancePct },
  };
}

export function checkSpreadTrap(spreadPct: number, maxSpreadTolerance = 0.8): GateResult {
  const passed = spreadPct <= maxSpreadTolerance;
  return {
    passed,
    reason: passed
      ? 'Spread wajar'
      : `Spread ${spreadPct.toFixed(2)}% > toleransi ${maxSpreadTolerance}%`,
    values: { spreadPct: round2(spreadPct), tolerance: maxSpreadTolerance },
  };
}

export function checkRsiGuard(rsi15m: number | null, maxRsi = 70): GateResult {
  if (rsi15m === null) {
    return {
      passed: true,
      reason: 'RSI tidak tersedia, gerbang lolos dengan peringatan',
      values: { rsi: -1 },
    };
  }
  const passed = rsi15m <= maxRsi;
  return {
    passed,
    reason: passed
      ? `RSI ${rsi15m.toFixed(1)} dalam batas aman`
      : `RSI ${rsi15m.toFixed(1)} > ${maxRsi} (Overbought)`,
    values: { rsi: round2(rsi15m), maxRsi },
  };
}

/**
 * Peak-to-trough equity kill switch plus an absolute equity floor.
 * Unlike the daily circuit breaker (24h cooldown, entries only), a drawdown
 * breach represents a slow multi-day bleed and halts until a manual reset.
 */
export function checkMaxDrawdown(
  currentEquityIdr: number,
  peakEquityIdr: number,
  maxDrawdownPct: number,
  equityFloorIdr: number
): GateResult {
  const drawdownPct =
    peakEquityIdr > 0 && currentEquityIdr < peakEquityIdr
      ? ((peakEquityIdr - currentEquityIdr) / peakEquityIdr) * 100
      : 0;

  const belowFloor = equityFloorIdr > 0 && currentEquityIdr < equityFloorIdr;
  const drawdownBreached = maxDrawdownPct > 0 && drawdownPct >= maxDrawdownPct;
  const passed = !belowFloor && !drawdownBreached;

  let reason = 'Drawdown dan equity floor dalam batas aman';
  if (belowFloor) {
    reason = `Equity Rp ${Math.round(currentEquityIdr).toLocaleString('id-ID')} di bawah floor Rp ${Math.round(equityFloorIdr).toLocaleString('id-ID')}`;
  } else if (drawdownBreached) {
    reason = `Drawdown ${drawdownPct.toFixed(2)}% >= batas ${maxDrawdownPct}% dari puncak Rp ${Math.round(peakEquityIdr).toLocaleString('id-ID')}`;
  }

  return {
    passed,
    reason,
    values: {
      equityIdr: Math.round(currentEquityIdr),
      peakEquityIdr: Math.round(peakEquityIdr),
      drawdownPct: round2(drawdownPct),
      maxDrawdownPct,
      equityFloorIdr: Math.round(equityFloorIdr),
      belowFloor,
    },
  };
}

/**
 * Caps a per-trade allocation to a percentage of current equity.
 * The legacy max_allocation_per_trade_idr is an absolute number that does not
 * scale with account growth; this cap closes that hole when configured.
 */
export function capAllocationByEquityPercent(
  allocationIdr: number,
  equityIdr: number,
  maxAllocationPercent: number
): { allocationIdr: number; capped: boolean; capIdr: number } {
  if (maxAllocationPercent <= 0 || equityIdr <= 0) {
    return { allocationIdr, capped: false, capIdr: 0 };
  }
  const capIdr = Math.round((equityIdr * maxAllocationPercent) / 100);
  if (allocationIdr <= capIdr) {
    return { allocationIdr, capped: false, capIdr };
  }
  return { allocationIdr: capIdr, capped: true, capIdr };
}

export interface CapitalPlan {
  capitalIdr: number;
  profile: 'conservative' | 'balanced' | 'aggressive';
  maxAllocationPerTradeIdr: number;
  maxActiveTrades: number;
  trailingStopPercent: number;
  dailyLossLimitPercent: number;
  slippageTolerancePercent: number;
  takeProfitStep1Percent: number;
  takeProfitTarget2Percent: number;
  totalCommitmentIdr: number;
  cashBufferIdr: number;
  cashBufferPercent: number;
  minVolumeIdr: number;
  allowNewListings: boolean;
  allowedCoinsOnly: string;
  notes: string[];
}

/**
 * Pure Mathematical Capital Allocation & Risk Sizing Engine
 * Sizes positions proportionally while strictly enforcing Indodax exchange constraints.
 */
export function calculateCapitalAllocation(
  capitalIdrInput: number,
  profile: 'conservative' | 'balanced' | 'aggressive' = 'balanced'
): CapitalPlan {
  const INDODAX_MIN_TRADE_IDR = 10000;
  const capitalIdr = Math.max(INDODAX_MIN_TRADE_IDR, Math.round(Number(capitalIdrInput) || 100000));
  const notes: string[] = [];

  let baseAllocationPct = 0.3;
  let targetMaxTrades = 3;
  let trailingStop = 2.5;
  let dailyLoss = 5.0;
  let slippage = 0.8;
  let tp1 = 5.0;
  let tp2 = 10.0;
  let minVolume = 200000000;
  let allowNew = true;
  let allowedCoins = '';

  if (profile === 'conservative') {
    baseAllocationPct = 0.2;
    targetMaxTrades = capitalIdr >= 5000000 ? 3 : 2;
    trailingStop = 1.8;
    dailyLoss = 3.0;
    slippage = 0.5;
    tp1 = 3.5;
    tp2 = 7.0;
    minVolume = 1000000000;
    allowNew = false;
    allowedCoins = 'btc,eth,sol,bnb,xrp';
  } else if (profile === 'aggressive') {
    baseAllocationPct = capitalIdr >= 1000000 ? 0.3 : 0.45;
    targetMaxTrades = capitalIdr >= 500000 ? 3 : 2;
    trailingStop = 3.5;
    dailyLoss = 8.0;
    slippage = 1.2;
    tp1 = 7.5;
    tp2 = 15.0;
    minVolume = 50000000;
    allowNew = true;
    allowedCoins = '';
  }

  // Calculate proportional per-trade allocation
  let allocation = Math.round(capitalIdr * baseAllocationPct);
  if (allocation < INDODAX_MIN_TRADE_IDR) {
    allocation = INDODAX_MIN_TRADE_IDR;
    notes.push(`Alokasi per koin disesuaikan ke minimum order Indodax (Rp ${INDODAX_MIN_TRADE_IDR.toLocaleString('id-ID')}).`);
  }

  // Calculate safe number of active positions so total exposure <= capital
  const maxAllowedByCapital = Math.max(1, Math.floor(capitalIdr / allocation));
  const maxActiveTrades = Math.min(targetMaxTrades, maxAllowedByCapital);

  // If allocation * maxActiveTrades > capital, adjust allocation downward to fit
  if (allocation * maxActiveTrades > capitalIdr) {
    allocation = Math.max(INDODAX_MIN_TRADE_IDR, Math.floor(capitalIdr / maxActiveTrades));
  }

  const totalCommitmentIdr = allocation * maxActiveTrades;
  const cashBufferIdr = Math.max(0, capitalIdr - totalCommitmentIdr);
  const cashBufferPercent = Math.round((cashBufferIdr / capitalIdr) * 100);

  if (capitalIdr < 50000) {
    notes.push('Saran: Modal di bawah Rp 50.000 memiliki ruang diversifikasi terbatas.');
  }

  return {
    capitalIdr,
    profile,
    maxAllocationPerTradeIdr: allocation,
    maxActiveTrades,
    trailingStopPercent: trailingStop,
    dailyLossLimitPercent: dailyLoss,
    slippageTolerancePercent: slippage,
    takeProfitStep1Percent: tp1,
    takeProfitTarget2Percent: tp2,
    totalCommitmentIdr,
    cashBufferIdr,
    cashBufferPercent,
    minVolumeIdr: minVolume,
    allowNewListings: allowNew,
    allowedCoinsOnly: allowedCoins,
    notes,
  };
}

import { EventEmitter } from 'events';
import crypto from 'crypto';
import { db } from '../../db/index.js';

export type AgentTopic = 'opportunity.signal' | 'research.brief' | 'trade.proposal' | 'risk.verdict';

export interface AgentMessage<T = unknown> {
  id: string; // `msg_${Date.now()}_${randomHex}`
  topic: AgentTopic;
  from: string; // agentId / service
  correlationId?: string;
  ts: number;
  ttlMs: number;
  payload: T;
  tokenCost?: number;
}

export type MessageHandler<T = any> = (msg: AgentMessage<T>) => void | Promise<void>;

export class AgentBus {
  private emitter: EventEmitter;
  private insertStmt: any;

  constructor() {
    this.emitter = new EventEmitter({ captureRejections: true });
    this.emitter.setMaxListeners(50);

    // Global error listener to prevent uncaughtException crash
    this.emitter.on('error', (err) => {
      console.warn('[AgentBus Error]', err?.message || err);
    });

    try {
      this.insertStmt = db.prepare(`
        INSERT INTO agent_messages (id, topic, from_agent, correlation_id, ts, ttl_ms, payload, consumed_by)
        VALUES (?, ?, ?, ?, ?, ?, ?, ?)
      `);
    } catch {
      // In case DB is not yet initialized
    }
  }

  public publish<T = unknown>(
    topic: AgentTopic,
    from: string,
    payload: T,
    options: { correlationId?: string; ttlMs?: number; tokenCost?: number } = {}
  ): AgentMessage<T> {
    const id = `msg_${Date.now()}_${crypto.randomBytes(4).toString('hex')}`;
    const ts = Date.now();
    const ttlMs = options.ttlMs ?? 15 * 60 * 1000; // default 15 min TTL

    const msg: AgentMessage<T> = {
      id,
      topic,
      from,
      correlationId: options.correlationId,
      ts,
      ttlMs,
      payload,
      tokenCost: options.tokenCost ?? 0,
    };

    // 1. Durable outbox persistence in SQLite
    try {
      if (!this.insertStmt) {
        this.insertStmt = db.prepare(`
          INSERT INTO agent_messages (id, topic, from_agent, correlation_id, ts, ttl_ms, payload, consumed_by)
          VALUES (?, ?, ?, ?, ?, ?, ?, ?)
        `);
      }
      this.insertStmt.run(
        msg.id,
        msg.topic,
        msg.from,
        msg.correlationId || null,
        msg.ts,
        msg.ttlMs,
        JSON.stringify(msg.payload),
        null
      );
    } catch (err: any) {
      console.warn('[AgentBus Outbox Warning] Gagal menyimpan message:', err?.message);
    }

    // 2. Dispatch in-process event
    this.emitter.emit(topic, msg);
    return msg;
  }

  public subscribe<T = unknown>(topic: AgentTopic, handler: MessageHandler<T>): () => void {
    const safeWrapper = async (msg: AgentMessage<T>) => {
      try {
        await Promise.resolve(handler(msg));
      } catch (err: any) {
        console.warn(`[AgentBus Handler Error on ${topic}]:`, err?.message || err);
      }
    };

    this.emitter.on(topic, safeWrapper);
    return () => {
      this.emitter.off(topic, safeWrapper);
    };
  }

  public getRecentMessages(topic?: AgentTopic, limit = 50): AgentMessage[] {
    try {
      const rows = topic
        ? (db.prepare(`
            SELECT * FROM agent_messages
            WHERE topic = ?
            ORDER BY ts DESC
            LIMIT ?
          `).all(topic, limit) as any[])
        : (db.prepare(`
            SELECT * FROM agent_messages
            ORDER BY ts DESC
            LIMIT ?
          `).all(limit) as any[]);

      return rows.map((r) => ({
        id: r.id,
        topic: r.topic,
        from: r.from_agent,
        correlationId: r.correlation_id,
        ts: r.ts,
        ttlMs: r.ttl_ms,
        payload: JSON.parse(r.payload || '{}'),
      }));
    } catch {
      return [];
    }
  }
}

