const FINAL_ORDER_STATUSES = new Set(['FILLED', 'CANCELED', 'CANCELLED', 'REJECTED', 'EXPIRED']);

const sleep = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms));

export class IndodaxClient {
  private publicBaseUrl = 'https://indodax.com';
  private tradeBaseUrl = 'https://api.indodax.com';
  private tapiBaseUrl = 'https://indodax.com/tapi';
  private knownPairIds: Set<string> = new Set();
  private pairsCache: Map<string, IndodaxPair> = new Map();
  private pairsCacheTime = 0;
  private pairsInFlight: Promise<IndodaxPair[]> | null = null;
  private summariesCache: { tickers: Record<string, IndodaxSummaryTicker>; prices_24h: Record<string, string> } | null = null;
  private summariesCacheTime = 0;
  private summariesInFlight: Promise<{ tickers: Record<string, IndodaxSummaryTicker>; prices_24h: Record<string, string> }> | null = null;
  private summariesTtlMs = 6000; // 6s TTL cache to avoid ~6,000 redundant requests/day

  private depthCache: Map<string, { data: IndodaxDepth; time: number }> = new Map();
  private depthTtlMs = 4000; // 4s TTL cache for orderbook depth

  private onNewCoinCallback?: (coin: { symbol: string; name: string; price: number; volume: number }) => void;

  constructor() {
    this.loadKnownPairs();
  }

  public setNewCoinCallback(cb: (coin: { symbol: string; name: string; price: number; volume: number }) => void) {
    this.onNewCoinCallback = cb;
  }

  private loadKnownPairs() {
    try {
      // Migrate legacy alert rows so an upgrade never re-announces old listings
      db.prepare(
        'INSERT OR IGNORE INTO known_pairs (pair_id, first_seen_at) SELECT LOWER(symbol), detected_at FROM new_coin_alerts'
      ).run();

      const rows = db.prepare('SELECT pair_id FROM known_pairs').all() as Array<{ pair_id: string }>;
      for (const row of rows) {
        this.knownPairIds.add(row.pair_id.toLowerCase());
      }
    } catch (err) {
      console.warn('[Indodax] Gagal memuat known pairs registry:', err instanceof Error ? err.message : err);
    }
  }

  // --- Public REST API Methods ---

  /**
   * Parse respon JSON secara aman dengan perlindungan terhadap halaman error HTML 502/504 Cloudflare
   */
  private async safeParseResponse<T = any>(res: Response, endpointName: string): Promise<T> {
    const rawText = await res.text();
    if (!res.ok) {
      const cleanSnippet = rawText.slice(0, 150).replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
      throw new Error(`Indodax ${endpointName} gagal (${res.status} ${res.statusText}): ${cleanSnippet || 'Gateway/Cloudflare error'}`);
    }
    try {
      return JSON.parse(rawText) as T;
    } catch {
      const cleanSnippet = rawText.slice(0, 150).replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
      throw new Error(`Indodax ${endpointName} mengembalikan non-JSON response (${res.status}): ${cleanSnippet || 'Invalid JSON format'}`);
    }
  }

  public async getPairs(forceRefresh = false): Promise<IndodaxPair[]> {
    const now = Date.now();
    if (!forceRefresh && this.pairsCache.size > 0 && now - this.pairsCacheTime < 10 * 60 * 1000) {
      return Array.from(this.pairsCache.values());
    }
    if (this.pairsInFlight) {
      return this.pairsInFlight;
    }

    this.pairsInFlight = this.fetchAndTrackPairs();
    try {
      return await this.pairsInFlight;
    } finally {
      this.pairsInFlight = null;
    }
  }

  private async fetchAndTrackPairs(): Promise<IndodaxPair[]> {
    const res = await fetch(`${this.publicBaseUrl}/api/pairs`);
    const pairs = await this.safeParseResponse<IndodaxPair[]>(res, 'getPairs');

    // Filter only IDR base currency pairs
    const idrPairs = pairs.filter(p => p.base_currency.toLowerCase() === 'idr');

    this.pairsCache.clear();
    for (const p of idrPairs) {
      this.pairsCache.set(p.id.toLowerCase(), p);
      this.pairsCache.set(p.symbol.toUpperCase(), p);
    }
    this.pairsCacheTime = Date.now();

    await this.trackPairUniverse(idrPairs);
    return idrPairs;
  }

  /**
   * Persists the full pair universe. The first run after install/upgrade seeds the
   * registry silently; later runs only raise alerts for pairs never seen before.
   */
  private async trackPairUniverse(idrPairs: IndodaxPair[]) {
    try {
      const seeded = getSetting('known_pairs_seeded', '0') === '1';
      const insertKnown = db.prepare(
        'INSERT OR IGNORE INTO known_pairs (pair_id, first_seen_at) VALUES (?, ?)'
      );
      const newPairs: IndodaxPair[] = [];
      const now = Date.now();

      for (const pair of idrPairs) {
        const id = pair.id.toLowerCase();
        insertKnown.run(id, now);
        if (seeded && !this.knownPairIds.has(id)) {
          newPairs.push(pair);
        }
        this.knownPairIds.add(id);
      }

      if (!seeded) {
        setSetting('known_pairs_seeded', '1');
        console.log(`[Indodax] Registry pair awal disimpan (${idrPairs.length} pair), tanpa alert massal.`);
        return;
      }

      for (const pair of newPairs) {
        let lastPrice = 0;
        let volume24h = 0;
        try {
          const { ticker } = await this.getTicker(pair.id);
          lastPrice = parseFloat(ticker?.last || '0') || 0;
          volume24h = parseFloat(ticker?.vol_idr || '0') || 0;
        } catch {
          // Alert still matters; price will be shown as unavailable
        }
        this.recordNewCoinListing(pair, lastPrice, volume24h);
      }
    } catch (err) {
      console.warn('[Indodax] Gagal memperbarui registry pair:', err instanceof Error ? err.message : err);
    }
  }

  public getPairRules(symbol: string): IndodaxPair | undefined {
    const clean = symbol.toLowerCase().replace('/', '').replace('_', '');
    return this.pairsCache.get(clean) || this.pairsCache.get(clean.toUpperCase());
  }

  public formatQuantity(symbol: string, rawQuantity: number): string {
    const pair = this.getPairRules(symbol);
    const increment = pair?.quantity_increment ? String(pair.quantity_increment) : '0.00000001';
    const decimals = increment.includes('.') ? increment.split('.')[1].length : 0;
    const factor = Math.pow(10, decimals);
    // Always floor to avoid exceeding available balance
    const floored = Math.floor(rawQuantity * factor) / factor;
    return floored.toFixed(decimals);
  }

  public getMinTradeIdr(symbol: string): number {
    const pair = this.getPairRules(symbol);
    return pair?.trade_min_base_currency || 10000;
  }

  public async getSummaries(force = false): Promise<{ tickers: Record<string, IndodaxSummaryTicker>; prices_24h: Record<string, string> }> {
    const now = Date.now();
    if (!force && this.summariesCache && now - this.summariesCacheTime < this.summariesTtlMs) {
      return this.summariesCache;
    }
    if (this.summariesInFlight) {
      return this.summariesInFlight;
    }

    this.summariesInFlight = (async () => {
      try {
        const res = await fetch(`${this.publicBaseUrl}/api/summaries`);
        const data = await this.safeParseResponse<{ tickers: Record<string, IndodaxSummaryTicker>; prices_24h: Record<string, string> }>(res, 'getSummaries');
        this.summariesCache = data;
        this.summariesCacheTime = Date.now();
        return data;
      } finally {
        this.summariesInFlight = null;
      }
    })();

    return this.summariesInFlight;
  }

  public async getDepth(pairId: string, force = false): Promise<IndodaxDepth> {
    let clean = pairId.toLowerCase().replace('/', '').replace('_', '');
    if (!clean.endsWith('idr') && !clean.endsWith('usdt')) {
      clean = `${clean}idr`;
    }
    const now = Date.now();
    const cached = this.depthCache.get(clean);
    if (!force && cached && now - cached.time < this.depthTtlMs) {
      return cached.data;
    }

    const res = await fetch(`${this.publicBaseUrl}/api/depth/${clean}`);
    const data = await this.safeParseResponse<IndodaxDepth>(res, `getDepth(${clean})`);
    this.depthCache.set(clean, { data, time: Date.now() });
    return data;
  }

  public async getTicker(pairId: string): Promise<{ ticker: IndodaxSummaryTicker }> {
    let clean = pairId.toLowerCase().replace('/', '').replace('_', '');
    if (!clean.endsWith('idr') && !clean.endsWith('usdt')) {
      clean = `${clean}idr`;
    }
    const res = await fetch(`${this.publicBaseUrl}/api/ticker/${clean}`);
    return await this.safeParseResponse<{ ticker: IndodaxSummaryTicker }>(res, `getTicker(${clean})`);
  }

  // --- Slippage & Liquidity Protection ---

  public calculateSlippage(
    depth: IndodaxDepth,
    side: 'buy' | 'sell',
    totalIdr: number
  ): { averageFillPrice: number; bestPrice: number; slippagePercent: number; isSufficientLiquidity: boolean } {
    const book = side === 'buy' ? depth.sell : depth.buy;
    if (!book || book.length === 0) {
      return { averageFillPrice: 0, bestPrice: 0, slippagePercent: 100, isSufficientLiquidity: false };
    }

    const bestPrice = parseFloat(book[0][0]);
    let remainingIdr = totalIdr;
    let totalSpentIdr = 0;
    let totalTradedCurrency = 0;

    for (const [priceStr, volStr] of book) {
      const price = parseFloat(priceStr);
      const volumeTraded = parseFloat(volStr);
      const orderVolumeIdr = price * volumeTraded;

      if (remainingIdr <= orderVolumeIdr) {
        const tradedAmount = remainingIdr / price;
        totalTradedCurrency += tradedAmount;
        totalSpentIdr += remainingIdr;
        remainingIdr = 0;
        break;
      } else {
        totalTradedCurrency += volumeTraded;
        totalSpentIdr += orderVolumeIdr;
        remainingIdr -= orderVolumeIdr;
      }
    }

    if (remainingIdr > 0) {
      return {
        averageFillPrice: totalSpentIdr / (totalTradedCurrency || 1),
        bestPrice,
        slippagePercent: 999,
        isSufficientLiquidity: false,
      };
    }

    const averageFillPrice = totalSpentIdr / totalTradedCurrency;
    const slippagePercent = Math.abs((averageFillPrice - bestPrice) / bestPrice) * 100;

    return {
      averageFillPrice,
      bestPrice,
      slippagePercent,
      isSufficientLiquidity: true,
    };
  }

  /**
   * Menghitung Bid-Ask Spread (%) untuk menghindari jebakan likuiditas tipis (spread trap).
   */
  public calculateSpread(depth: IndodaxDepth): { bestBid: number; bestAsk: number; spreadPercent: number } {
    const bestBid = depth.buy && depth.buy[0] ? parseFloat(depth.buy[0][0]) : 0;
    const bestAsk = depth.sell && depth.sell[0] ? parseFloat(depth.sell[0][0]) : 0;
    if (bestBid <= 0 || bestAsk <= 0) {
      return { bestBid, bestAsk, spreadPercent: 100 };
    }
    const spreadPercent = Math.abs((bestAsk - bestBid) / bestAsk) * 100;
    return { bestBid, bestAsk, spreadPercent: Number(spreadPercent.toFixed(2)) };
  }

  /**
   * Menghitung rasio dominasi volume Bid vs Ask (Depth Imbalance Ratio) pada 10 layer teratas.
   * Rasio > 1.0 menandakan dinding beli (buying wall) lebih tebal dari dinding jual.
   */
  public calculateDepthImbalance(depth: IndodaxDepth, layers: number = 10): number {
    const bids = (depth.buy || []).slice(0, layers);
    const asks = (depth.sell || []).slice(0, layers);
    const bidVolIdr = bids.reduce((acc, [p, v]) => acc + parseFloat(p) * parseFloat(v), 0);
    const askVolIdr = asks.reduce((acc, [p, v]) => acc + parseFloat(p) * parseFloat(v), 0);
    if (askVolIdr <= 0) return bidVolIdr > 0 ? 2.0 : 1.0;
    return Number((bidVolIdr / askVolIdr).toFixed(2));
  }

  // --- Official Private Trade API 2.0 (HMAC-SHA256) ---

  private getAuthCredentials(): { apiKey: string; secretKey: string } {
    const apiKey = getSetting('indodax_api_key', '');
    const secretKey = getSetting('indodax_secret_key', '');
    return { apiKey, secretKey };
  }

  private generateHmacSha256(data: string, secretKey: string): string {
    return crypto.createHmac('sha256', secretKey).update(data).digest('hex');
  }

  private static readonly MAX_PRIVATE_RETRIES = 3;

  private retryDelayMs(attempt: number, retryAfterHeader?: string | null): number {
    const retryAfter = parseFloat(retryAfterHeader || '0');
    if (Number.isFinite(retryAfter) && retryAfter > 0) {
      return Math.min(retryAfter * 1000, 15000);
    }
    // Exponential backoff with jitter: ~400ms, ~800ms, ~1600ms (+-25%)
    const base = 400 * Math.pow(2, attempt);
    const jitter = base * (0.75 + Math.random() * 0.5);
    return Math.min(Math.round(jitter), 8000);
  }

  /**
   * Sends a signed private request. GET/DELETE are retried on transient
   * failures (network error, 429, 5xx) with exponential backoff honoring
   * Retry-After. POST is NEVER retried blindly: createOrder is not idempotent
   * and a duplicate market order would double an entry — order intents cover
   * crash recovery for POSTs instead.
   */
  private async executePrivateRequest<T>(
    endpoint: string,
    method: 'GET' | 'POST' | 'DELETE',
    params: Record<string, string | number>,
    attempt = 0
  ): Promise<T> {
    const { apiKey, secretKey } = this.getAuthCredentials();
    if (!apiKey || !secretKey) {
      throw new Error('Indodax API Key / Secret Key belum dikonfigurasi di menu Settings.');
    }

    const timestamp = Date.now();
    const payload: Record<string, string | number> = {
      ...params,
      timestamp,
      recvWindow: 5000,
    };

    // Sort parameters alphabetically per TAPI v2 specification
    const sortedKeys = Object.keys(payload).sort();
    const queryString = sortedKeys.map(k => `${encodeURIComponent(k)}=${encodeURIComponent(payload[k])}`).join('&');
    const signature = this.generateHmacSha256(queryString, secretKey);

    const isGetOrDelete = method === 'GET' || method === 'DELETE';
    const url = `${this.tradeBaseUrl}${endpoint}${isGetOrDelete ? `?${queryString}&signature=${signature}` : ''}`;

    const headers: Record<string, string> = {
      Accept: 'application/json',
      'X-APIKEY': apiKey,
      Sign: signature,
    };

    if (method === 'POST') {
      headers['Content-Type'] = 'application/x-www-form-urlencoded';
    }

    const options: RequestInit = {
      method,
      headers,
    };

    if (method === 'POST') {
      options.body = queryString;
    }

    let res: Response;
    try {
      res = await fetch(url, options);
    } catch (err: any) {
      if (isGetOrDelete && attempt < IndodaxClient.MAX_PRIVATE_RETRIES) {
        await sleep(this.retryDelayMs(attempt));
        return this.executePrivateRequest<T>(endpoint, method, params, attempt + 1);
      }
      throw new Error(`Indodax Trade API network error (${endpoint}): ${err?.message || err}`);
    }

    if (!res.ok) {
      const retryable = res.status === 429 || res.status >= 500;
      if (retryable && isGetOrDelete && attempt < IndodaxClient.MAX_PRIVATE_RETRIES) {
        await sleep(this.retryDelayMs(attempt, res.headers.get('retry-after')));
        return this.executePrivateRequest<T>(endpoint, method, params, attempt + 1);
      }
      const rawText = await res.text().catch(() => '');
      const cleanSnippet = rawText.slice(0, 150).replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
      throw new Error(`Indodax Trade API gagal (${endpoint} ${res.status} ${res.statusText}): ${cleanSnippet || 'Gateway/Cloudflare error'}`);
    }

    const rawText = await res.text();
    let data: any;
    try {
      data = JSON.parse(rawText);
    } catch {
      const cleanSnippet = rawText.slice(0, 150).replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
      throw new Error(`Indodax Trade API mengembalikan non-JSON response (${endpoint} ${res.status}): ${cleanSnippet || 'Invalid JSON format'}`);
    }

    if (data && typeof data.code === 'number' && data.code < 0) {
      throw new Error(`Indodax Trade API error: ${data.msg || res.statusText} (code: ${data.code})`);
    }

    return data as T;
  }

  private async callPrivateApi<T>(
    endpoint: string,
    method: 'GET' | 'POST' | 'DELETE',
    params: Record<string, string | number> = {}
  ): Promise<T> {
    return this.executePrivateRequest<T>(endpoint, method, params);
  }

  // --- Official Endpoints per INDODAX-TradeAPI-2.md ---

  /**
   * GET /api/v2/account
   * Mengambil saldo akun (balances: [{ asset: 'IDR', free: '...', locked: '...' }])
   * Responses are deduplicated for 1s and concurrent calls share one request:
   * the engine reads the account every loop and per-tick paths read it too.
   */
  private accountCache: { data: any; time: number } | null = null;
  private accountInFlight: Promise<any> | null = null;

  public async getAccountInfo(): Promise<{
    canTrade: boolean;
    canWithdraw: boolean;
    accountType: string;
    balances: Array<{ asset: string; free: string; locked: string }>;
    data?: { balance: { idr: number } }; // backward compatibility
  }> {
    const now = Date.now();
    if (this.accountCache && now - this.accountCache.time < 1000) {
      return this.accountCache.data;
    }
    if (this.accountInFlight) {
      return this.accountInFlight;
    }

    this.accountInFlight = (async () => {
      try {
        const result = await this.callPrivateApi<any>('/api/v2/account', 'GET', {});

        // Compute IDR free balance for convenience
        let idrFree = 0;
        if (Array.isArray(result?.balances)) {
          const idrEntry = result.balances.find((b: any) => String(b.asset).toUpperCase() === 'IDR');
          if (idrEntry) idrFree = parseFloat(idrEntry.free) || 0;
        }

        // Attach backward-compatible helper field
        result.data = { balance: { idr: idrFree } };
        this.accountCache = { data: result, time: Date.now() };
        return result;
      } finally {
        this.accountInFlight = null;
      }
    })();

    return this.accountInFlight;
  }

  public async getIdrBalance(): Promise<{ free: number; locked: number; total: number }> {
    try {
      const acc = await this.getAccountInfo();
      if (Array.isArray(acc?.balances)) {
        const idrEntry = acc.balances.find((b: any) => String(b.asset).toUpperCase() === 'IDR');
        if (idrEntry) {
          const free = parseFloat(idrEntry.free) || 0;
          const locked = parseFloat(idrEntry.locked) || 0;
          return { free, locked, total: free + locked };
        }
      }
      return { free: 0, locked: 0, total: 0 };
    } catch {
      return { free: 0, locked: 0, total: 0 };
    }
  }

  /**
   * POST /api/v2/order
   * Membuat order baru spot trading sesuai spesifikasi resmi INDODAX Trade API v2.0
   * 
   * Rules:
   * - MARKET BUY: Wajib menggunakan `quoteOrderQty` (IDR), tanpa `price` dan tanpa `quantity`.
   * - MARKET SELL: Menggunakan `quantity` (koin), tanpa `price` dan tanpa `quoteOrderQty`.
   * - LIMIT: Menggunakan `price`, `quantity`, dan `timeInForce: 'GTC'`.
   */
  public async createOrder(options: {
    symbol: string;
    side: 'BUY' | 'SELL' | 'buy' | 'sell';
    type: 'MARKET' | 'LIMIT' | 'market' | 'limit';
    quoteOrderQty?: number; // Nominal IDR untuk MARKET BUY
    quantity?: number; // Jumlah koin untuk MARKET SELL atau LIMIT
    price?: number; // Harga satuan koin untuk LIMIT
    newClientOrderId?: string; // Client-defined idempotency key (alphanumeric _-, max 36)
  }): Promise<IndodaxOrderResponse & { order_id?: string }> {
    const upperSymbol = options.symbol.toUpperCase().replace('/', '').replace('_', '');
    const upperSide = options.side.toUpperCase() as 'BUY' | 'SELL';
    const upperType = options.type.toUpperCase() as 'MARKET' | 'LIMIT';

    const params: Record<string, string | number> = {
      symbol: upperSymbol,
      side: upperSide,
      type: upperType,
    };

    if (options.newClientOrderId) {
      // Official spec: alphanumeric + `_` + `-` only, max 36 characters
      params.newClientOrderId = String(options.newClientOrderId).replace(/[^A-Za-z0-9_-]/g, '').slice(0, 36);
    }

    if (upperType === 'MARKET') {
      if (upperSide === 'BUY') {
        if (!options.quoteOrderQty || options.quoteOrderQty <= 0) {
          throw new Error('MARKET BUY membutuhkan parameter quoteOrderQty (nominal IDR).');
        }
        // Round to whole rupiah
        params.quoteOrderQty = Math.floor(options.quoteOrderQty);
      } else {
        // MARKET SELL
        if (!options.quantity || options.quantity <= 0) {
          throw new Error('MARKET SELL membutuhkan parameter quantity (jumlah koin).');
        }
        params.quantity = this.formatQuantity(upperSymbol, options.quantity);
      }
    } else {
      // LIMIT order
      if (!options.price || options.price <= 0) throw new Error('LIMIT order membutuhkan harga (price).');
      if (!options.quantity || options.quantity <= 0) throw new Error('LIMIT order membutuhkan jumlah koin (quantity).');
      params.price = Math.floor(options.price);
      params.quantity = this.formatQuantity(upperSymbol, options.quantity);
      params.timeInForce = 'GTC';
    }

    const result = await this.callPrivateApi<any>('/api/v2/order', 'POST', params);

    // Normalize order response. Never fabricate a fake id: fall back to the
    // clientOrderId (traceable via the order-intent journal) instead of Date.now().
    const orderId = result.orderId || result.order_id || params.newClientOrderId || '';
    return {
      ...result,
      orderId,
      order_id: String(orderId), // For backward compatibility
      clientOrderId: result.clientOrderId || params.newClientOrderId || '',
    };
  }

  /**
   * DELETE /api/v2/order
   * Batalkan pending order berdasarkan symbol dan orderId
   */
  public async cancelOrder(symbol: string, orderId: string | number): Promise<any> {
    const upperSymbol = symbol.toUpperCase().replace('/', '').replace('_', '');
    return await this.callPrivateApi('/api/v2/order', 'DELETE', {
      symbol: upperSymbol,
      orderId: String(orderId),
    });
  }

  /**
   * GET /api/v2/openOrders
   * Ambil daftar order yang masih pending
   */
  public async getOpenOrders(symbol?: string): Promise<any[]> {
    const params: Record<string, string> = {};
    if (symbol) {
      params.symbol = symbol.toUpperCase().replace('/', '').replace('_', '');
    }
    return await this.callPrivateApi('/api/v2/openOrders', 'GET', params);
  }

  /**
   * GET /api/v2/order
   * Ambil detail status order
   */
  public async getOrder(symbol: string, orderId: string | number): Promise<any> {
    const upperSymbol = symbol.toUpperCase().replace('/', '').replace('_', '');
    return await this.callPrivateApi('/api/v2/order', 'GET', {
      symbol: upperSymbol,
      orderId: String(orderId),
    });
  }

  /**
   * GET /api/v2/order via origClientOrderId. Used by order-intent recovery:
   * after a crash between "order sent" and "fill recorded", the journal's
   * client_order_id is the only durable handle for the in-flight order.
   */
  public async getOrderByClientOrderId(symbol: string, clientOrderId: string): Promise<any> {
    const upperSymbol = symbol.toUpperCase().replace('/', '').replace('_', '');
    return await this.callPrivateApi('/api/v2/order', 'GET', {
      symbol: upperSymbol,
      origClientOrderId: clientOrderId,
    });
  }

  /**
   * Normalizes fill data across possible v2 response shapes. Never guesses a
   * fill quantity unless the order is explicitly FILLED and a fallback is known.
   */
  public extractOrderFill(
    raw: any,
    fallback: { requestedQty?: number; expectedPrice?: number } = {}
  ): IndodaxFillInfo {
    const src = raw?.data?.order ?? raw?.data ?? raw?.order ?? raw?.return ?? raw ?? {};
    const num = (value: any): number => {
      const parsed = parseFloat(value);
      return Number.isFinite(parsed) ? parsed : 0;
    };

    const status = String(src.status ?? src.orderStatus ?? src.order_status ?? src.state ?? '').toUpperCase();
    let executedQty = num(
      src.executedQty ?? src.executed_qty ?? src.filledQty ?? src.filled_qty ?? src.executed ?? 0
    );
    let quoteQty = num(
      src.cummulativeQuoteQty ??
        src.cummulative_quote_qty ??
        src.quoteQty ??
        src.quote_qty ??
        src.total ??
        0
    );
    let averagePrice = num(src.avgPrice ?? src.averagePrice ?? src.avg_price ?? src.average ?? 0);

    if (status === 'FILLED' && executedQty <= 0) {
      if (fallback.requestedQty && fallback.requestedQty > 0) {
        executedQty = fallback.requestedQty;
      } else if (quoteQty > 0 && fallback.expectedPrice && fallback.expectedPrice > 0) {
        executedQty = quoteQty / fallback.expectedPrice;
      }
    }
    if (averagePrice <= 0 && executedQty > 0 && quoteQty > 0) {
      averagePrice = quoteQty / executedQty;
    }
    if (averagePrice <= 0 && executedQty > 0 && fallback.expectedPrice && fallback.expectedPrice > 0) {
      averagePrice = fallback.expectedPrice;
    }
    if (quoteQty <= 0 && executedQty > 0 && averagePrice > 0) {
      quoteQty = executedQty * averagePrice;
    }

    const explicitlyFilled = executedQty > 0 && num(
      src.executedQty ?? src.executed_qty ?? src.filledQty ?? src.filled_qty ?? src.executed ?? 0
    ) > 0;
    const verified = explicitlyFilled || (status === 'FILLED' && executedQty > 0);

    const isFinal =
      FINAL_ORDER_STATUSES.has(status) ||
      (!status &&
        fallback.requestedQty !== undefined &&
        executedQty >= fallback.requestedQty * 0.999999);

    return {
      orderId: String(src.orderId ?? src.order_id ?? src.id ?? raw?.orderId ?? raw?.order_id ?? ''),
      status: status || 'UNKNOWN',
      executedQty,
      quoteQty,
      averagePrice,
      verified,
      isFinal,
    };
  }

  public async waitForOrderFill(
    symbol: string,
    orderId: string | number,
    rawResponse?: any,
    fallback: { requestedQty?: number; expectedPrice?: number } = {},
    timeoutMs = 5000
  ): Promise<IndodaxFillInfo> {
    let fill = this.extractOrderFill(rawResponse ?? { orderId }, fallback);
    if (fill.isFinal) return fill;

    const deadline = Date.now() + timeoutMs;
    while (Date.now() < deadline) {
      await sleep(400);
      try {
        const order = await this.getOrder(symbol, orderId);
        fill = this.extractOrderFill(order, fallback);
        if (fill.isFinal) return fill;
      } catch {
        // Transient network/API issue: retry until the deadline
      }
    }
    return fill;
  }

  // --- Official Deadman Switch Heartbeat (Deadman-switch.md) ---
  // Protocol: POST https://indodax.com/tapi/countdownCancelAll
  // Authentication: HMAC-SHA512 with Header 'Key' and 'Sign'

  public async pingDeadmanSwitch(pairs: string[] = ['btc_idr']): Promise<boolean> {
    const enabled = getSetting('deadman_switch_enabled', '1') === '1';
    if (!enabled) return true;

    try {
      const { apiKey, secretKey } = this.getAuthCredentials();
      if (!apiKey || !secretKey) return false;

      const timestamp = Date.now();
      const pairString = pairs
        .map(p => {
          const clean = p.toLowerCase().replace('/', '');
          return clean.includes('_') ? clean : `${clean.replace('idr', '')}_idr`;
        })
        .join(',');

      const countdownTime = 60000; // 60 detik countdown
      const recvWindow = 5000;

      const payload = `pair=${encodeURIComponent(pairString)}&countdownTime=${countdownTime}&timestamp=${timestamp}&recvWindow=${recvWindow}`;
      const sign = crypto.createHmac('sha512', secretKey).update(payload).digest('hex');

      const res = await fetch(`${this.tapiBaseUrl}/countdownCancelAll`, {
        method: 'POST',
        headers: {
          'Key': apiKey,
          'Sign': sign,
          'Content-Type': 'application/x-www-form-urlencoded',
        },
        body: payload,
      });

      if (!res.ok) {
        return false;
      }

      const data = await this.safeParseResponse<any>(res, 'pingDeadmanSwitch');
      return data?.success === 1;
    } catch {
      return false;
    }
  }

  // Helper to cancel the deadman switch countdown when safely shutting down
  public async cancelDeadmanSwitch(pairs: string[] = ['btc_idr']): Promise<boolean> {
    try {
      const { apiKey, secretKey } = this.getAuthCredentials();
      if (!apiKey || !secretKey) return true;

      const timestamp = Date.now();
      const pairString = pairs
        .map(p => {
          const clean = p.toLowerCase().replace('/', '');
          return clean.includes('_') ? clean : `${clean.replace('idr', '')}_idr`;
        })
        .join(',');

      const payload = `pair=${encodeURIComponent(pairString)}&countdownTime=0&timestamp=${timestamp}&recvWindow=5000`;
      const sign = crypto.createHmac('sha512', secretKey).update(payload).digest('hex');

      const res = await fetch(`${this.tapiBaseUrl}/countdownCancelAll`, {
        method: 'POST',
        headers: {
          'Key': apiKey,
          'Sign': sign,
          'Content-Type': 'application/x-www-form-urlencoded',
        },
        body: payload,
      });

      if (!res.ok) return false;
      const data = await this.safeParseResponse<any>(res, 'cancelDeadmanSwitch');
      return data?.success === 1;
    } catch {
      return false;
    }
  }

  // --- New Coin Detector Helper ---

  private recordNewCoinListing(pair: IndodaxPair, lastPrice: number, volume24h: number) {
    try {
      const result = db.prepare(`
        INSERT OR IGNORE INTO new_coin_alerts (id, symbol, name, initial_price, current_price, volume_24h, surge_percent, detected_at, status)
        VALUES (?, ?, ?, ?, ?, ?, 0, ?, 'monitoring')
      `).run(
        `alert_${pair.id}_${Date.now()}`,
        pair.id.toLowerCase(),
        pair.description,
        lastPrice,
        lastPrice,
        volume24h,
        Date.now()
      );

      if (result.changes === 0) return;

      console.log(`[Indodax] Listing baru terdeteksi: ${pair.description} (${pair.id.toUpperCase()}) @ ${lastPrice}`);

      if (this.onNewCoinCallback) {
        this.onNewCoinCallback({
          symbol: pair.id,
          name: pair.description,
          price: lastPrice,
          volume: volume24h,
        });
      }
    } catch (err) {
      console.error('Error recording new coin listing:', err);
    }
  }
}

export const indodax = new IndodaxClient();

import WebSocket from 'ws';
import { saveCandles } from '../candles/store.js';

export interface RealCandle {
  time: string;
  timestamp: number;
  open: number;
  high: number;
  low: number;
  close: number;
  volume: number; // Volume in IDR
  rawVolume?: number; // Volume in traded coin
}

export interface IndodaxTrade {
  date: string; // timestamp in seconds
  price: string;
  amount: string;
  tid: string;
  type: 'buy' | 'sell';
}

export class IndodaxMarketStream {
  private ws: WebSocket | null = null;
  private isConnected = false;
  private subscribedPairs: Set<string> = new Set(['btcidr', 'ethidr', 'solidr', 'pepeidr', 'dogeidr', 'xrpidr']);
  private staticToken =
    'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJleHAiOjE5NDY2MTg0MTV9.UR1lBM6Eqh0yWz-PVirw1uPCxe60FdchR8eNVdsskeo';
  private pingInterval: NodeJS.Timeout | null = null;
  private highFreqPollInterval: NodeJS.Timeout | null = null;
  private lastTradeTidMap: Map<string, string> = new Map();
  private lastPriceMap: Map<string, number> = new Map();
  private onTickCallback?: (tick: { pair: string; price: number; volume: number; timestamp: number; high24h?: number; low24h?: number; side?: 'buy' | 'sell' }) => void;

  public setTickCallback(cb: (tick: { pair: string; price: number; volume: number; timestamp: number; high24h?: number; low24h?: number; side?: 'buy' | 'sell' }) => void) {
    this.onTickCallback = cb;
  }

  /**
   * Mengambil Data Candlestick Resmi dari Indodax TradingView UDF Engine (history_v2)
   * DAN menggabungkan candle berjalan (forming candle) secara real-time dengan transaksi terbaru!
   */
  public async getRealCandles(pairId: string, timeframe: '15m' | '1h' | '4h' | '1d' = '1h'): Promise<RealCandle[]> {
    const cleanPair = pairId.toLowerCase().replace('/', '').replace('_', '');
    const cleanSymbol = cleanPair.toUpperCase();
    const to = Math.floor(Date.now() / 1000);

    let tfParam = '60';
    let rangeSec = 86400 * 7; // default 1h: 7 hari = ~168 candle

    if (timeframe === '15m') {
      tfParam = '15';
      rangeSec = 86400 * 2; // 2 hari = ~192 candle
    } else if (timeframe === '1h') {
      tfParam = '60';
      rangeSec = 86400 * 7;
    } else if (timeframe === '4h') {
      tfParam = '240';
      rangeSec = 86400 * 25; // 25 hari = ~150 candle
    } else if (timeframe === '1d') {
      tfParam = '1D';
      rangeSec = 86400 * 90; // 90 hari = ~90 candle
    }

    const from = to - rangeSec;
    const historyUrl = `https://indodax.com/tradingview/history_v2?from=${from}&to=${to}&tf=${tfParam}&symbol=${cleanSymbol}`;

    let candles: RealCandle[] = [];

    // 1. Ambil data historis dari history_v2
    try {
      const res = await fetch(historyUrl, {
        headers: {
          'Accept': 'application/json',
          'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AI-Trading/1.0',
        },
      });

      if (res.ok) {
        const rawBars = await res.json();
        if (Array.isArray(rawBars) && rawBars.length > 0) {
          candles = rawBars.map((b: any) => {
            const timeSec = typeof b.Time === 'number' ? b.Time : parseInt(b.Time, 10);
            const open = typeof b.Open === 'number' ? b.Open : parseFloat(b.Open);
            const high = typeof b.High === 'number' ? b.High : parseFloat(b.High);
            const low = typeof b.Low === 'number' ? b.Low : parseFloat(b.Low);
            const close = typeof b.Close === 'number' ? b.Close : parseFloat(b.Close);
            const rawVol = typeof b.Volume === 'number' ? b.Volume : parseFloat(b.Volume || '0');
            const volIdr = rawVol * close;

            return {
              time: timeframe === '1d'
                ? new Date(timeSec * 1000).toLocaleDateString('id-ID', { day: '2-digit', month: '2-digit' })
                : new Date(timeSec * 1000).toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit' }),
              timestamp: timeSec * 1000,
              open,
              high,
              low,
              close,
              volume: Math.round(volIdr),
              rawVolume: rawVol,
            };
          });

          this.persistCandlesThrottled(cleanPair, timeframe, rawBars);
        }
      }
    } catch (err: any) {
      console.warn(`[IndodaxMarketStream] history_v2 gagal untuk ${cleanSymbol}:`, err.message);
    }

    // Jika history_v2 kosong, ambil fallback dari trades
    if (candles.length === 0) {
      candles = await this.getCandlesFromTradesFallback(cleanPair, timeframe);
    }

    // 2. INTEGRASI FORMING CANDLE REAL-TIME:
    // history_v2 memiliki cache CDN ~60 detik. Kita gabungkan transaksi & ticker terkini
    // agar candle terakhir SELALU BERDETAK dan bila waktu berganti, membentuk candle baru seketika!
    try {
      const bucketSec =
        timeframe === '15m' ? 15 * 60 : timeframe === '1h' ? 60 * 60 : timeframe === '4h' ? 4 * 3600 : 86400;
      const currentBucketSec = Math.floor(to / bucketSec) * bucketSec;
      const currentBucketMs = currentBucketSec * 1000;

      const [tickerRes, tradesRes] = await Promise.all([
        fetch(`https://indodax.com/api/ticker/${cleanPair}`),
        fetch(`https://indodax.com/api/trades/${cleanPair}`),
      ]);

      const tickerData: any = tickerRes.ok ? await tickerRes.json() : null;
      const tradesData: any = tradesRes.ok ? await tradesRes.json() : [];

      const liveLastPrice = parseFloat(tickerData?.ticker?.last || '0');

      if (liveLastPrice > 0 && candles.length > 0) {
        const lastCandle = candles[candles.length - 1];

        // Kumpulkan semua transaksi yang terjadi di dalam bucket interval saat ini
        const bucketTrades = Array.isArray(tradesData)
          ? tradesData.filter((t: any) => parseInt(t.date, 10) >= currentBucketSec)
          : [];

        let bucketVolIdr = 0;
        let bucketHigh = liveLastPrice;
        let bucketLow = liveLastPrice;

        for (const t of bucketTrades) {
          const p = parseFloat(t.price);
          const a = parseFloat(t.amount);
          bucketVolIdr += p * a;
          bucketHigh = Math.max(bucketHigh, p);
          bucketLow = Math.min(bucketLow, p);
        }

        if (lastCandle.timestamp === currentBucketMs) {
          // Update candle aktif saat ini dengan harga dan transaksi detik ini
          lastCandle.close = liveLastPrice;
          lastCandle.high = Math.max(lastCandle.high, bucketHigh);
          lastCandle.low = Math.min(lastCandle.low, bucketLow);
          if (bucketVolIdr > 0) lastCandle.volume = Math.max(lastCandle.volume, Math.round(bucketVolIdr));
        } else if (lastCandle.timestamp < currentBucketMs) {
          // WAKTU TELAH BERGANTI KE INTERVAL BARU! BUAT CANDLE BARU OTOMATIS!
          const newTimeStr = timeframe === '1d'
            ? new Date(currentBucketMs).toLocaleDateString('id-ID', { day: '2-digit', month: '2-digit' })
            : new Date(currentBucketMs).toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit' });

          candles.push({
            time: newTimeStr,
            timestamp: currentBucketMs,
            open: lastCandle.close,
            high: Math.max(lastCandle.close, bucketHigh),
            low: Math.min(lastCandle.close, bucketLow),
            close: liveLastPrice,
            volume: Math.round(bucketVolIdr),
          });
        }
      }
    } catch {}

    return candles;
  }

  // Fallback agregasi dari /api/trades/:pair
  private async getCandlesFromTradesFallback(cleanPair: string, timeframe: string): Promise<RealCandle[]> {
    try {
      const res = await fetch(`https://indodax.com/api/trades/${cleanPair}`);
      if (!res.ok) throw new Error(`HTTP ${res.status}: ${res.statusText}`);
      const trades = (await res.json()) as IndodaxTrade[];

      const tickerRes = await fetch(`https://indodax.com/api/ticker/${cleanPair}`);
      const tickerData: any = tickerRes.ok ? await tickerRes.json() : null;
      const lastTickerPrice = parseFloat(tickerData?.ticker?.last || '0');

      if (!Array.isArray(trades) || trades.length === 0) {
        return this.generateFallbackFromTicker(lastTickerPrice, timeframe);
      }

      trades.sort((a, b) => parseInt(a.date, 10) - parseInt(b.date, 10));

      const bucketSeconds =
        timeframe === '15m'
          ? 15 * 60
          : timeframe === '1h'
          ? 60 * 60
          : timeframe === '4h'
          ? 4 * 60 * 60
          : 24 * 60 * 60;

      const candleMap = new Map<number, RealCandle>();

      for (const t of trades) {
        const timeSec = parseInt(t.date, 10);
        const bucketTime = Math.floor(timeSec / bucketSeconds) * bucketSeconds;
        const price = parseFloat(t.price);
        const amount = parseFloat(t.amount);
        const volIdr = price * amount;

        if (!candleMap.has(bucketTime)) {
          candleMap.set(bucketTime, {
            time: new Date(bucketTime * 1000).toLocaleTimeString('id-ID', {
              hour: '2-digit',
              minute: '2-digit',
            }),
            timestamp: bucketTime * 1000,
            open: price,
            high: price,
            low: price,
            close: price,
            volume: volIdr,
          });
        } else {
          const c = candleMap.get(bucketTime)!;
          c.high = Math.max(c.high, price);
          c.low = Math.min(c.low, price);
          c.close = price;
          c.volume += volIdr;
        }
      }

      const candles = Array.from(candleMap.values());
      return candles.length > 0 ? candles : this.generateFallbackFromTicker(lastTickerPrice, timeframe);
    } catch {
      return [];
    }
  }

  /**
   * Subscribe pasangan koin baru secara dinamis ke WebSocket dan Poller
   */
  public subscribePair(pairId: string) {
    const cleanPair = pairId.toLowerCase().replace('/', '').replace('_', '');
    if (this.subscribedPairs.has(cleanPair)) return;

    this.subscribedPairs.add(cleanPair);

    if (this.isConnected && this.ws && this.ws.readyState === WebSocket.OPEN) {
      this.ws.send(JSON.stringify({
        method: 1,
        params: { channel: `chart:tick-${cleanPair}` },
        id: Math.floor(Math.random() * 10000),
      }));
      this.ws.send(JSON.stringify({
        method: 1,
        params: { channel: `market:trade-activity-${cleanPair}` },
        id: Math.floor(Math.random() * 10000),
      }));
    }
  }

  private isPolling = false;
  private lastWsMessageTime = 0;

  /**
   * Gentle Rate-Limit-Safe Poller (setiap 5 detik):
   * Menggunakan 1 panggilan tunggal ke /api/summaries untuk memantau SEMUA pasangan koin sekaligus,
   * sehingga konsumsi request hanya ~12-15 req/menit (jauh di bawah batas 180 req/menit Indodax).
   */
  private startGentlePoller() {
    if (this.highFreqPollInterval) clearInterval(this.highFreqPollInterval);

    this.highFreqPollInterval = setInterval(async () => {
      if (this.isPolling) return; // In-flight guard: cegah request tumpang tindih
      this.isPolling = true;

      try {
        const res = await fetch('https://indodax.com/api/summaries', {
          headers: { 'Accept': 'application/json' },
        });

        if (res.ok) {
          const data: any = await res.json();
          const tickers = data?.tickers || {};

          for (const pair of this.subscribedPairs) {
            const tickerKey = `${pair.toLowerCase().replace('idr', '')}_idr`;
            const tData = tickers[tickerKey] || tickers[pair.toLowerCase()];
            if (!tData) continue;

            const currentPrice = parseFloat(tData.last || '0');
            const high24h = parseFloat(tData.high || '0');
            const low24h = parseFloat(tData.low || '0');
            const volIdr = parseFloat(tData.vol_idr || '0');

            const lastPrice = this.lastPriceMap.get(pair);
            const hasPriceMoved = currentPrice > 0 && currentPrice !== lastPrice;

            if (hasPriceMoved) {
              this.lastPriceMap.set(pair, currentPrice);

              if (this.onTickCallback && currentPrice > 0) {
                this.onTickCallback({
                  pair,
                  price: currentPrice,
                  volume: volIdr,
                  high24h,
                  low24h,
                  side: 'buy',
                  timestamp: Date.now(),
                });
              }
            }
          }
        }
      } catch (err: any) {
        // Silently catch network blip
      } finally {
        this.isPolling = false;
      }
    }, 5000);
  }

  /**
   * Connect ke Official Indodax Market Data WebSocket (Marketdata-websocket.md)
   * Base URL: wss://ws3.indodax.com/ws/
   */
  public startLiveSocket() {
    // Jalankan Gentle Poller sebagai pendamping aman rate limit
    this.startGentlePoller();

    if (this.isConnected || this.ws) return;

    try {
      this.ws = new WebSocket('wss://ws3.indodax.com/ws/');

      this.ws.on('open', () => {
        this.isConnected = true;
        console.log('[IndodaxMarketStream] Terhubung ke Official Market Data WebSocket (wss://ws3.indodax.com/ws/)');

        // 1. Authenticate dengan static token resmi Indodax
        this.ws?.send(
          JSON.stringify({
            params: { token: this.staticToken },
            id: 1,
          })
        );

        // 2. Setup Ping/Pong keep-alive setiap 20 detik (Marketdata-websocket.md - Ping/Pong method 7)
        if (this.pingInterval) clearInterval(this.pingInterval);
        this.pingInterval = setInterval(() => {
          if (this.ws && this.ws.readyState === WebSocket.OPEN) {
            this.ws.send(JSON.stringify({ method: 7, id: 999 }));
          }
        }, 20000);
      });

      this.ws.on('message', (raw) => {
        try {
          const msg = JSON.parse(raw.toString());

          // A. Respon autentikasi berhasil -> Subscribe channel utama
          if (msg.id === 1 && msg.result?.client) {
            console.log(`[IndodaxMarketStream] Autentikasi WebSocket berhasil. Client ID: ${msg.result.client}`);

            // Subscribe ke market summary 24 jam (semua koin sekaligus secara real-time)
            this.ws?.send(
              JSON.stringify({
                method: 1,
                params: { channel: 'market:summary-24h' },
                id: 10,
              })
            );

            // Subscribe ke chart tick & trade activity untuk setiap pair terpilih
            let reqId = 20;
            for (const pair of this.subscribedPairs) {
              this.ws?.send(
                JSON.stringify({
                  method: 1,
                  params: { channel: `chart:tick-${pair}` },
                  id: reqId++,
                })
              );
              this.ws?.send(
                JSON.stringify({
                  method: 1,
                  params: { channel: `market:trade-activity-${pair}` },
                  id: reqId++,
                })
              );
            }
          }

          // B. Event Streaming: Market Summary 24 Jam (Real-time updates untuk seluruh koin)
          else if (msg.result?.channel === 'market:summary-24h') {
            const summaryData = msg.result.data?.data;
            if (Array.isArray(summaryData)) {
              for (const item of summaryData) {
                // Format: [pair, timestamp, last, low, high, price24hAgo, idrVol, coinVol]
                if (Array.isArray(item) && item.length >= 7) {
                  const [pair, epoch, last, low, high, , idrVol] = item;
                  if (this.onTickCallback && typeof last === 'number') {
                    this.onTickCallback({
                      pair: String(pair).toLowerCase(),
                      price: last,
                      volume: parseFloat(idrVol || '0'),
                      high24h: typeof high === 'number' ? high : parseFloat(high),
                      low24h: typeof low === 'number' ? low : parseFloat(low),
                      timestamp: (typeof epoch === 'number' ? epoch : parseInt(epoch, 10)) * 1000,
                    });
                  }
                }
              }
            }
          }

          // C. Event Streaming: Chart Tick Spesifik (chart:tick-<pair>)
          else if (msg.result?.channel?.startsWith('chart:tick-')) {
            const pair = msg.result.channel.replace('chart:tick-', '');
            const tickArray = msg.result.data?.data?.[0];
            if (Array.isArray(tickArray)) {
              const [epoch, , price, volStr] = tickArray;
              if (this.onTickCallback) {
                this.onTickCallback({
                  pair: pair.toLowerCase(),
                  price: parseFloat(price),
                  volume: parseFloat(volStr || '0'),
                  timestamp: (typeof epoch === 'number' ? epoch : parseInt(epoch, 10)) * 1000,
                });
              }
            }
          }

          // D. Event Streaming: Trade Activity (market:trade-activity-<pair>)
          else if (msg.result?.channel?.startsWith('market:trade-activity-')) {
            const tradeArray = msg.result.data?.data?.[0];
            if (Array.isArray(tradeArray)) {
              const [pair, epoch, , side, filledPrice, idrVol] = tradeArray;
              if (this.onTickCallback) {
                this.onTickCallback({
                  pair: String(pair).toLowerCase(),
                  price: parseFloat(filledPrice),
                  volume: parseFloat(idrVol || '0'),
                  side: side === 'sell' ? 'sell' : 'buy',
                  timestamp: (typeof epoch === 'number' ? epoch : parseInt(epoch, 10)) * 1000,
                });
              }
            }
          }
        } catch {}
      });

      this.ws.on('close', () => {
        this.isConnected = false;
        this.ws = null;
        if (this.pingInterval) clearInterval(this.pingInterval);
        setTimeout(() => this.startLiveSocket(), 5000);
      });

      this.ws.on('error', (err) => {
        this.isConnected = false;
        this.ws?.close();
      });
    } catch (err) {
      console.warn('[IndodaxMarketStream] Gagal inisialisasi:', err);
    }
  }

  /**
   * Fail-Closed Guard: Jika candlestick resmi dan riwayat trades bursa tidak tersedia,
   * kembalikan data flat harga aktual saat ini tanpa kurva sinus sintetis (Math.sin).
   * Mencegah kalkulasi indikator teknikal (RSI, EMA, ATR) dari data halusinasi.
   */
  private generateFallbackFromTicker(basePrice: number, _timeframe: string): RealCandle[] {
    if (!basePrice || basePrice <= 0) return [];

    const now = Date.now();
    const timeStr = new Date(now).toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit' });
    return [
      {
        time: timeStr,
        timestamp: now,
        open: basePrice,
        high: basePrice,
        low: basePrice,
        close: basePrice,
        volume: 0,
      },
    ];
  }

  public stop() {
    if (this.highFreqPollInterval) {
      clearInterval(this.highFreqPollInterval);
      this.highFreqPollInterval = null;
    }
    if (this.pingInterval) {
      clearInterval(this.pingInterval);
      this.pingInterval = null;
    }
    if (this.ws) {
      this.ws.close();
      this.ws = null;
    }
    this.isConnected = false;
  }

  /** Observability: live feed connection state for /api/metrics. */
  public getLiveStatus(): { connected: boolean } {
    return { connected: this.isConnected && this.ws?.readyState === WebSocket.OPEN };
  }

  private lastPersistAt = new Map<string, number>();

  /**
   * Write-through research cache: closed candles land in SQLite so backtests
   * and walk-forward runs stop depending on the undocumented history_v2
   * endpoint. Throttled to one write per pair/timeframe per 5 minutes.
   */
  private persistCandlesThrottled(pair: string, timeframe: string, rawBars: any[]) {
    const key = `${pair}:${timeframe}`;
    const now = Date.now();
    if (now - (this.lastPersistAt.get(key) || 0) < 5 * 60 * 1000) return;
    this.lastPersistAt.set(key, now);

    try {
      saveCandles(
        pair,
        timeframe,
        rawBars.map((b: any) => ({
          timestamp: (typeof b.Time === 'number' ? b.Time : parseInt(b.Time, 10)) * 1000,
          open: typeof b.Open === 'number' ? b.Open : parseFloat(b.Open),
          high: typeof b.High === 'number' ? b.High : parseFloat(b.High),
          low: typeof b.Low === 'number' ? b.Low : parseFloat(b.Low),
          close: typeof b.Close === 'number' ? b.Close : parseFloat(b.Close),
          volume: typeof b.Volume === 'number' ? b.Volume : parseFloat(b.Volume || '0'),
        }))
      );
    } catch {
      // Best-effort; saveCandles already logs and swallows.
    }
  }
}

export const indodaxMarketStream = new IndodaxMarketStream();

import { db } from '../../db/index.js';
import type { BacktestBar } from '../backtest/index.js';

/**
 * Local candle persistence (research cache).
 *
 * Candles observed by the live engine are written through to SQLite so
 * backtests, walk-forward optimization, and offline AI-gate replays can run
 * without re-scraping the undocumented TradingView history endpoint. A 90-day
 * ring buffer keeps the file bounded.
 */

const RETENTION_DAYS = 90;

export function saveCandles(pair: string, timeframe: string, bars: BacktestBar[]): number {
  if (!Array.isArray(bars) || bars.length === 0) return 0;
  try {
    const cleanPair = pair.toLowerCase().replace('/', '').replace('_', '');
    const insert = db.prepare(`
      INSERT OR REPLACE INTO candles (pair, timeframe, ts, open, high, low, close, volume)
      VALUES (?, ?, ?, ?, ?, ?, ?, ?)
    `);
    const cutoff = Date.now() - RETENTION_DAYS * 86400 * 1000;

    const tx = db.transaction(() => {
      for (const bar of bars) {
        if (!(bar.timestamp > 0 && bar.close > 0)) continue;
        insert.run(cleanPair, timeframe, bar.timestamp, bar.open, bar.high, bar.low, bar.close, bar.volume);
      }
      db.prepare('DELETE FROM candles WHERE ts < ?').run(cutoff);
    });
    tx();
    return bars.length;
  } catch (err: any) {
    // Persistence is best-effort: research caching must never break trading.
    console.warn('[CandleStore] Gagal menyimpan candle:', err?.message);
    return 0;
  }
}

export function loadCandles(pair: string, timeframe: string, limit = 5000): BacktestBar[] {
  try {
    const cleanPair = pair.toLowerCase().replace('/', '').replace('_', '');
    return db.prepare(`
      SELECT ts, open, high, low, close, volume FROM candles
      WHERE pair = ? AND timeframe = ?
      ORDER BY ts DESC LIMIT ?
    `).all(cleanPair, timeframe, limit)
      .map((row: any) => ({
        timestamp: row.ts,
        open: row.open,
        high: row.high,
        low: row.low,
        close: row.close,
        volume: row.volume || 0,
      }))
      .reverse();
  } catch {
    return [];
  }
}

export function candleStoreStats(): Record<string, { pairs: number; candles: number; oldestTs: number }> {
  const rows = db.prepare(`
    SELECT timeframe, COUNT(DISTINCT pair) as pairs, COUNT(*) as candles, MIN(ts) as oldestTs
    FROM candles GROUP BY timeframe
  `).all() as Array<{ timeframe: string; pairs: number; candles: number; oldestTs: number }>;
  const out: Record<string, { pairs: number; candles: number; oldestTs: number }> = {};
  for (const r of rows) {
    out[r.timeframe] = { pairs: r.pairs, candles: r.candles, oldestTs: r.oldestTs };
  }
  return out;
}
